import json
from html import unescape
from html.parser import HTMLParser
class Text(HTMLParser):
 def __init__(self): super().__init__(); self.out=[]
 def handle_data(self,x): self.out.append(x)
 def handle_starttag(self,t,a):
  if t in ('p','br','div'): self.out.append('\\n')
def text(x):
 p=Text();p.feed(x);return unescape(''.join(p.out)).strip()
s=json.load(open('source.json')); a=json.load(open('answer.json'))
for src,out in zip(s[:8],a[:8]):
 print('\\nARTICLE',src['number'],'\\nSOURCE\\n'+text(src['source_xml']))
 print('NOTES SOURCE',repr(src['source_notes_xml']))
 print('PROPOSITION\\n'+text(out['proposed_xml']))
PY"

